functions.mk872LevelProgressHtml:
function mk872LevelProgressHtml(profileXP,variant="full"){
 const p=mk872GetLevelProgress(profileXP),compact=variant!=="full",small=variant==="tiny";
 const label=`Уровень ${p.currentLevel}: ${Math.floor(p.xpIntoLevel)} из ${p.xpNeededForLevel} XP до уровня ${p.currentLevel+1}; осталось ${Math.ceil(p.xpRemaining)} XP`;
 const labelText=small?`Ур. ${p.currentLevel} · ${Math.round(p.progressPercent)}%`:`Уровень ${p.currentLevel} → ${p.currentLevel+1}`;
 const details=small?`${Math.ceil(p.xpRemaining)} XP осталось`:`${Math.floor(p.xpIntoLevel)} / ${p.xpNeededForLevel} XP · до ур. ${p.currentLevel+1}: ${Math.ceil(p.xpRemaining)} XP`;
 return `<div class="mk872-xp-progress ${compact?'compact':''} ${variant==='top'?'mk872-top-progress':''} ${variant==='tiny'?'mk872-leader-progress':''}" role="progressbar" aria-label="${label}" aria-valuemin="0" aria-valuemax="${p.xpNeededForLevel}" aria-valuenow="${Math.floor(p.xpIntoLevel)}"><div class="mk872-xp-head"><span>${labelText}</span>${small?'':`<span>${Math.round(p.progressPercent)}%</span>`}</div><div class="mk872-xp-track"><span class="mk872-xp-fill" style="width:${p.progressPercent}%"></span></div><div class="mk872-xp-foot">${details}</div></div>`;
}

